"use strict";

const http = require("http");
const https = require("https");
const zlib = require("zlib");
const { URL } = require("url");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

const PAGE_HEADERS = {
  "user-agent": UA,
  accept:
    "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
  "accept-language": "en-US,en;q=0.9",
  "accept-encoding": "gzip, deflate, br",
  "sec-ch-ua": '"Chromium";v="126", "Google Chrome";v="126", "Not;A=Brand";v="24"',
  "sec-ch-ua-mobile": "?0",
  "sec-ch-ua-platform": '"Windows"',
  "sec-fetch-dest": "document",
  "sec-fetch-mode": "navigate",
  "sec-fetch-site": "none",
  "upgrade-insecure-requests": "1",
};

const cleanUrl = (u) =>
  u
    ? String(u)
        .replace(/\\u002F/g, "/")
        .replace(/\\\//g, "/")
        .replace(/&amp;/g, "&")
    : null;

function toInt(v) {
  if (typeof v === "number") return Number.isFinite(v) ? v : null;
  if (typeof v === "string" && v.trim() !== "") {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

function unwrap(v) {
  return v && typeof v === "object" && "value" in v ? v.value : v;
}

class Jar {
  constructor() {
    this.map = new Map();
  }
  absorb(res) {
    let lines = [];
    if (res && res.headers && Array.isArray(res.headers["set-cookie"])) {
      lines = res.headers["set-cookie"];
    } else if (
      res &&
      res.headers &&
      typeof res.headers.getSetCookie === "function"
    ) {
      lines = res.headers.getSetCookie();
    }
    for (const line of lines) {
      const pair = String(line).split(";")[0];
      const i = pair.indexOf("=");
      if (i > 0) this.map.set(pair.slice(0, i).trim(), pair.slice(i + 1).trim());
    }
  }
  toString() {
    return [...this.map.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
  }
}

function parseNextData(html) {
  const m = String(html || "").match(
    /<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/
  );
  if (!m) return null;
  try {
    return JSON.parse(m[1]);
  } catch {
    return null;
  }
}

function requestText(currentUrl, jar, redirectsLeft) {
  return new Promise((resolve, reject) => {
    let parsed;
    try {
      parsed = new URL(currentUrl);
    } catch {
      reject(new Error("Invalid Snapchat URL: " + currentUrl));
      return;
    }
    const lib = parsed.protocol === "http:" ? http : https;
    if (!lib || typeof lib.get !== "function") {
      reject(new Error("Snapchat self-scrape: https module is unavailable"));
      return;
    }
    const headers = { ...PAGE_HEADERS };
    const cookie = jar ? jar.toString() : "";
    if (cookie) headers.cookie = cookie;

    const req = lib.get(parsed, { headers }, (res) => {
      if (jar) jar.absorb(res);
      const status = res.statusCode || 0;

      if (
        status >= 300 &&
        status < 400 &&
        res.headers.location &&
        redirectsLeft > 0
      ) {
        res.resume();
        res.on("end", () => {
          let next;
          try {
            next = new URL(res.headers.location, parsed).toString();
          } catch {
            reject(new Error("Snapchat self-scrape: bad redirect location"));
            return;
          }
          requestText(next, jar, redirectsLeft - 1).then(resolve, reject);
        });
        res.on("error", reject);
        return;
      }

      let stream = res;
      const encoding = String(res.headers["content-encoding"] || "").toLowerCase();
      if (encoding === "gzip") stream = res.pipe(zlib.createGunzip());
      else if (encoding === "deflate") stream = res.pipe(zlib.createInflate());
      else if (encoding === "br") stream = res.pipe(zlib.createBrotliDecompress());

      const chunks = [];
      stream.on("data", (c) => chunks.push(c));
      stream.on("end", () =>
        resolve({
          html: Buffer.concat(chunks).toString("utf8"),
          finalUrl: parsed.toString(),
          status,
        })
      );
      stream.on("error", reject);
      if (stream !== res) res.on("error", reject);
    });
    req.setTimeout(25000, () => {
      req.destroy(new Error("Snapchat page request timed out"));
    });
    req.on("error", reject);
  });
}

async function fetchPage(url, jar, hasData, attempts = 6) {
  let lastHtml = "";
  let lastFinalUrl = url;
  for (let i = 0; i < attempts; i++) {
    try {
      const { html, finalUrl } = await requestText(url, jar, 5);
      lastHtml = html || "";
      lastFinalUrl = finalUrl || url;
      if (lastHtml && hasData(lastHtml)) return { html: lastHtml, finalUrl: lastFinalUrl };
    } catch {
    }
    await new Promise((r) => setTimeout(r, 800));
  }
  return { html: lastHtml, finalUrl: lastFinalUrl };
}

function findFeedSnap(pageProps, snapId) {
  const stories =
    (pageProps.spotlightFeed && pageProps.spotlightFeed.spotlightStories) || [];
  for (const entry of stories) {
    const story = entry && entry.story;
    if (!story || !Array.isArray(story.snapList)) continue;
    for (const snap of story.snapList) {
      const id = unwrap(snap.snapId);
      if (!snapId || id === snapId) {
        return { snap, story, metadata: entry.metadata || null };
      }
    }
  }
  return null;
}

function shapeVideo(pageProps, snapId, finalUrl) {
  const vm = pageProps.videoMetadata || null;
  const feed = findFeedSnap(pageProps, snapId);
  const snap = feed ? feed.snap : null;
  const snapUrls = (snap && snap.snapUrls) || {};
  const creator =
    vm && vm.creator
      ? vm.creator.personCreator ||
        (vm.creator.$case === "personCreator" ? vm.creator.personCreator : null) ||
        null
      : null;

  const videoUrl = (vm && vm.contentUrl) || snapUrls.mediaUrl || null;
  const thumbnail =
    (vm && vm.thumbnailUrl) ||
    unwrap(snapUrls.mediaPreviewUrl) ||
    (feed && feed.story ? unwrap(feed.story.thumbnailUrl) : null) ||
    null;
  const id =
    snapId ||
    (snap ? unwrap(snap.snapId) : null) ||
    (finalUrl && (finalUrl.match(/spotlight\/([A-Za-z0-9_-]+)/) || [])[1]) ||
    null;

  return {
    id,
    title: vm ? vm.name || null : null,
    caption: vm ? vm.embeddedTextCaption || null : null,
    description: vm ? vm.description || null : null,
    author: creator
      ? {
          username: creator.username || null,
          fullName: creator.name || null,
          followers: toInt(creator.followerCount),
        }
      : null,
    media: {
      video: videoUrl,
      thumbnail,
    },
    url:
      finalUrl && /snapchat\.com\//.test(finalUrl)
        ? finalUrl
        : id
          ? `https://www.snapchat.com/spotlight/${id}`
          : null,
  };
}

function parseSnapInput(input) {
  const s = String(input || "").trim();
  let m = s.match(/snapchat\.com\/t\/([A-Za-z0-9_-]+)/i);
  if (m) return { kind: "share", code: m[1], url: `https://www.snapchat.com/t/${m[1]}` };
  m = s.match(/snapchat\.com\/(?:@[^/]+\/)?spotlight\/([A-Za-z0-9_-]{10,})/i);
  if (m) return { kind: "spotlight", id: m[1], url: `https://www.snapchat.com/spotlight/${m[1]}` };
  if (/snapchat\.com\//i.test(s)) return { kind: "url", url: s };
  if (/^[A-Za-z0-9_-]{20,}$/.test(s))
    return { kind: "spotlight", id: s, url: `https://www.snapchat.com/spotlight/${s}` };
  return null;
}

module.exports = async function fetchSelf(url) {
  const parsed = parseSnapInput(url);
  if (!parsed) {
    throw new Error(
      "Snapchat self-scrape: invalid Snapchat Spotlight URL or ID (only spotlight links are supported)"
    );
  }

  const jar = new Jar();
  const wantedId = parsed.id || null;
  const { html, finalUrl } = await fetchPage(parsed.url, jar, (h) => {
    const nd = parseNextData(h);
    if (!nd || !nd.props || !nd.props.pageProps) return false;
    const pp = nd.props.pageProps;
    if (pp.videoMetadata && pp.videoMetadata.contentUrl) return true;
    return !!findFeedSnap(pp, wantedId);
  });

  const nd = parseNextData(html);
  const pp = nd && nd.props ? nd.props.pageProps : null;
  if (!pp || (!pp.videoMetadata && !findFeedSnap(pp, wantedId))) {
    throw new Error(
      "Snapchat self-scrape: could not extract this snap -- it may be deleted, private, or Snapchat changed its page format"
    );
  }

  const canonicalId =
    wantedId ||
    (finalUrl && (finalUrl.match(/spotlight\/([A-Za-z0-9_-]+)/) || [])[1]) ||
    null;
  const scraped = shapeVideo(pp, canonicalId, finalUrl);

  const video = cleanUrl(scraped.media && scraped.media.video);
  if (!video) {
    throw new Error("Snapchat self-scrape: this snap page exposed no media URL");
  }
  const thumbnail = cleanUrl(scraped.media && scraped.media.thumbnail);
  const author =
    scraped.author && (scraped.author.username || scraped.author.fullName)
      ? scraped.author.username || scraped.author.fullName
      : null;
  const title =
    scraped.title || scraped.caption || scraped.description || "Snapchat Video";

  return {
    success: true,
    source: "Snapchat",
    data: {
      title: title || "Snapchat Video",
      author,
      thumbnail: thumbnail || null,
      download: {
        video,
        videos: [{ quality: "HD", url: video }],
        photos: [],
      },
    },
  };
};
